const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const { StudentGradeBook, SchoolAuthorization } = require('../models/education');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'k12-portal.yaml'),
    validateRequests: true
  })
);

app.get('/api/v1/schools/:schoolId/students/:studentId/report-card', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { schoolId, studentId } = req.params;

  // Verify that the caller is the student, a designated parent/guardian, or an authorized teacher
  const isAuthorized = await SchoolAuthorization.canViewStudentGrades(
    req.user.id,
    schoolId,
    studentId
  );

  if (!isAuthorized) {
    return res.status(403).json({ error: 'Access denied: caller not authorized to view this student record' });
  }

  const record = await StudentGradeBook.findOne({
    where: { schoolId, studentId }
  });

  if (!record) {
    return res.status(404).json({ error: 'Student record not found' });
  }

  res.json({
    studentId: record.studentId,
    gpa: record.gpa,
    termGrades: record.termGrades,
    teacherRemarks: record.teacherRemarks
  });
});

app.listen(5008);
